import assert from "node:assert/strict";
import fs from "node:fs";
import test from "node:test";

const read = (path) => JSON.parse(fs.readFileSync(new URL(path, import.meta.url)));
const plan = read("../shift-plan.json");
const capture = read("./cold-cycle.json");
const night = read("../night.json");

const close = (actual, expected) => {
  assert.ok(Math.abs(actual - expected) <= 1e-9, `${actual} != ${expected}`);
};

const availableKw = capture.samples.map(
  (sample) =>
    ((sample.acMeterEndKwh - sample.acMeterStartKwh) * 60) / sample.minutes,
);

const departures = (requestedKw, efficiency = 0.9) => {
  const applied = requestedKw.map((request, slot) =>
    Math.min(request, availableKw[slot]),
  );
  return {
    applied,
    kwh: [
      night.buses[0].startKwh +
        efficiency * night.slotHours * (applied[0] + applied[1]),
      night.buses[1].startKwh +
        efficiency * night.slotHours * (applied[2] + applied[3]),
    ],
  };
};

test("COLD-17 shows the old 70 kW request is clipped to 60 kW", () => {
  assert.deepEqual(availableKw, [80, 40, 60, 60]);
  const old = departures([80, 40, 70, 50]);
  assert.deepEqual(old.applied, [80, 40, 60, 50]);
  close(old.kwh[0], 126);
  close(old.kwh[1], 125.5);
  close(130 - old.kwh[1], 4.5);
});

test("the corrected A/A/B/B = 80/40/60/60 sheet is within COLD-17 limits and closes both gaps at 0.90", () => {
  assert.deepEqual(plan.acKw, [80, 40, 60, 60]);
  const corrected = departures(plan.acKw);
  assert.deepEqual(corrected.applied, [80, 40, 60, 60]);
  assert.ok(corrected.applied.every((power, slot) => power <= availableKw[slot]));
  close(corrected.kwh[0], 126);
  close(corrected.kwh[1], 130);
});

